/* Shared bilingual behaviour. All translations and navigation exist in the HTML. */
(()=>{const tr=document.documentElement.lang==='tr';const toggle=document.querySelector('.mobile-toggle'),nav=document.getElementById('nav');document.addEventListener('keydown',e=>{if(e.key==='Escape'&&nav?.classList.contains('open')){nav.classList.remove('open');toggle?.setAttribute('aria-expanded','false');toggle?.focus()}});const form=document.getElementById('brief');if(!form||!tr)return;const next=document.getElementById('next'),review=document.getElementById('review');const serviceNames={'Photography':'Fotoğraf','Film production':'Film prodüksiyonu','Photography & film':'Fotoğraf ve film'};const countryNames={'UAE':'BAE','Egypt':'Mısır','Saudi Arabia':'Suudi Arabistan','Other':'Diğer'};function localize(){const step=[...document.querySelectorAll('.form-step')].findIndex(e=>!e.hidden);next.textContent=step===2?'Brief’i hazırla ↗':'Devam ↗';if(review){const country=countryNames[form.elements.country.value]||form.elements.country.value,service=serviceNames[form.elements.service.value]||form.elements.service.value;review.textContent=[form.elements.property.value,country+' / '+form.elements.city.value,service].join(' · ')}}next.addEventListener('click',localize);document.getElementById('back')?.addEventListener('click',localize);document.getElementById('download')?.addEventListener('click',e=>{e.stopImmediatePropagation();const labels={property:'ŞİRKET / PROJE',country:'ÜLKE',city:'ŞEHİR',service:'HİZMET',timing:'TARİH',details:'PROJE DETAYLARI',name:'AD',email:'E-POSTA'};const lines=[...new FormData(form)].map(([k,v])=>(labels[k]||k)+': '+(k==='country'?(countryNames[v]||v):k==='service'?(serviceNames[v]||v):v));const url=URL.createObjectURL(new Blob(['CHARLOT CREA — PROJE BRİEFİ (DEMO)\n\n'+lines.join('\n')],{type:'text/plain;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='charlot-crea-proje-briefi.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)},{capture:true});localize()})();
